    /**
     * Tests getting all Territorys.
     *
     * @return    Collection
     */
    public List<Territory> testGetAll() throws Throwable {
    LOGGER.info( "TerritoryTest:testGetAll() - Retrieving Collection of Territorys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Territory : " );
    List<Territory> collection  = null;

    try {
        // call the static get method on the TerritoryService
        collection = service.getAllTerritory();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Territory currEntity  = null;
            Iterator<Territory> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTerritoryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

